package com.gerenciadorrural.modules.organizations.api;
import com.gerenciadorrural.modules.organizations.application.TenantContextNotAvailableException; import com.gerenciadorrural.shared.api.error.ApiErrorResponse; import com.gerenciadorrural.shared.observability.RequestContextFilter; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.List;
@RestControllerAdvice class TenantContextExceptionHandler { @ExceptionHandler(TenantContextHeaderException.class) ResponseEntity<ApiErrorResponse> header(TenantContextHeaderException e,HttpServletRequest r){return error(HttpStatus.BAD_REQUEST,e.code,"Os headers de contexto são inválidos",r);} @ExceptionHandler(TenantContextNotAvailableException.class) ResponseEntity<ApiErrorResponse> unavailable(HttpServletRequest r){return error(HttpStatus.NOT_FOUND,"TENANT_CONTEXT_NOT_AVAILABLE","O contexto solicitado não está disponível",r);} private static ResponseEntity<ApiErrorResponse> error(HttpStatus s,String c,String m,HttpServletRequest r){Object id=r.getAttribute(RequestContextFilter.REQUEST_ID_ATTRIBUTE);return ResponseEntity.status(s).body(new ApiErrorResponse(c,m,s.value(),id==null?null:id.toString(),List.of(),Instant.now()));}}
